"use client";

import { useEffect, useState } from 'react';
import Lenis from 'lenis';
import IntroScene from '@/components/intro/IntroScene';
import HeroScene from '@/components/hero/HeroScene';

export default function Home() {
  const [introFinished, setIntroFinished] = useState(false);

  useEffect(() => {
    // Initialize lenis globally for smooth scrolling
    const lenis = new Lenis();

    function raf(time: number) {
      lenis.raf(time);
      requestAnimationFrame(raf);
    }

    requestAnimationFrame(raf);

    return () => {
      lenis.destroy();
    };
  }, []);

  return (
    <main className="min-h-screen bg-midnight text-warm-ivory">
      {!introFinished && <IntroScene onComplete={() => setIntroFinished(true)} />}
      
      {introFinished && (
        <>
          <HeroScene />
          {/* We will add Our Story, Gallery, and other sections here soon */}
        </>
      )}
    </main>
  );
}
